// Knowledge v2 T1 acceptance (approved 2026-11-09, at most 6 USD): word cards generated by the
// production code path with the new rules, into an in-memory database (tests/fake-supabase.mjs) —
// nothing reaches production. Real OpenAI, real references and Korp. Stops before the next card
// once the metered cost passes STOP_USD. Measures what only a generated card can show:
//   A. polysemous words: Lexin sense coverage of the new card vs the library's card of today;
//   B. homograph candidates (identify): the card written for the asked part of speech;
//   C. multi-word searches from the labelled calibration sets: public only when entry-worthy.
//   node --env-file=.env scripts/t1-acceptance.mjs [--limit N]
import { createClient } from "@supabase/supabase-js";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, appendFileSync } from "node:fs";
import { useSaldoFiles } from "../server-lexicon.mjs";
import { useReferenceFiles, referenceEntries } from "../server-references.mjs";
import { generateWordEntry, identityCandidates } from "../server-native.mjs";
import { senseCoverage } from "../server-evidence.mjs";
import { exampleUsesWord } from "../server-language-checks.mjs";
import { openaiCost } from "../server-prices.mjs";
import { fakeSupabase } from "../tests/fake-supabase.mjs";

const STOP_USD = 5;
const LIMIT = Number(process.argv[process.argv.indexOf("--limit") + 1]) || Infinity;
process.env.MULTIWORD_SEARCH_CLASSIFY = "on";
process.env.KNOWLEDGE_SENSE_COVERAGE = "on";
delete process.env.KORP_OFFLINE;
await useSaldoFiles();
await useReferenceFiles("data/reference");
const prod = createClient(process.env.VITE_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });

// Every OpenAI answer's usage, priced as the server prices it.
let spent = 0, calls = 0;
const realFetch = globalThis.fetch;
globalThis.fetch = async (url, init) => {
  const res = await realFetch(url, init);
  if (String(url).includes("api.openai.com")) {
    const body = await res.clone().json().catch(() => null);
    if (body?.usage) { spent += openaiCost(body.usage, body.model?.replace(/-\d{4}-\d{2}-\d{2}$/, "")).cost; calls++; }
  }
  return res;
};

const hash = (s) => createHash("sha1").update(s).digest("hex");
const sv = JSON.parse(readFileSync("data/reference/lexin-sv/index.json", "utf8"));
const en = JSON.parse(readFileSync("data/reference/lexin/index.json", "utf8"));
// A: words Lexin gives at least three senses with English, one part of speech, fixed by hash.
const poly = Object.keys(sv).filter((w) => /^[a-zåäö]+$/.test(w) && sv[w].length === 1 && ["noun", "verb", "adjective"].includes(sv[w][0].pos)
  && (en[w] || []).filter((e) => e.pos === sv[w][0].pos && e.english?.length).length >= 3)
  .sort((a, b) => hash(a).localeCompare(hash(b))).slice(0, 60).map((w) => ({ set: "A", word: w, pos: sv[w][0].pos }));
// B: spellings of several parts of speech or homographs.
const HOMO = ["visa", "fast", "lag", "man", "bank", "rätt", "vår", "kort", "led", "lov", "ton", "fil"];
const homo = [];
for (const w of HOMO) for (const c of await identityCandidates(prod, w)) homo.push({ set: "B", word: c.lemma, pos: c.pos, asked: w });
// C: the labelled multi-word sets (scripts/calibrate-multiword.mjs).
const cal = JSON.parse(readFileSync("data/reports/round-f/calibrate-multiword.json", "utf8"));
const label = (k) => (cal[k] || []).map((x) => (typeof x === "string" ? x : x.swedish || x.text || x.phrase)).filter(Boolean);
const multi = [
  ...["växande intresse", "ta flera beslut", "liknande system", "gå ner till stranden", "sätta upp regler för något", "tända eldar", ...label("free")].filter((w, i, a) => a.indexOf(w) === i).slice(0, 10).map((w) => ({ set: "C", word: w, label: "free" })),
  ...["tända eld", "fatta beslut", "starkt kaffe", "dricka kaffe", "stort intresse", "ställa en fråga", "borsta tänderna", "tvätta händerna", "lägga märke till", "dra slutsatser"].map((w) => ({ set: "C", word: w, label: "typical" })),
  ...["gå i taket", "ta illa upp", "slå två flugor i en smäll", "ha hand om något", "lägga näsan i blöt", "ta det lugnt", "hålla tummarna", "gå som på räls", "stå på sig", "ge upp"].map((w) => ({ set: "C", word: w, label: "idiom" })),
];
const todo = [...poly, ...homo, ...multi].slice(0, LIMIT);
console.log({ A: poly.length, B: homo.length, C: multi.length, running: todo.length });

// The library's card of today for the same word (old rules), for the coverage comparison.
async function libraryMeaning(word, pos) {
  const { data } = await prod.from("learning_objects").select("id, learning_object_translations(meaning, native_language)").eq("swedish", word).eq("part_of_speech", pos).neq("status", "retired").limit(1);
  return data?.[0]?.learning_object_translations?.find((t) => t.native_language === "en")?.meaning ?? null;
}
const coverage = (refs, pos, meaning) => {
  const s = senseCoverage(refs, pos, meaning || "", []).filter((x) => !x.particleVerb);
  return { senses: s.length, covered: s.filter((x) => x.covered).length };
};

const out = `data/reports/round-f/t1-acceptance-${new Date().toISOString().slice(0, 10)}.ndjson`;
writeFileSync(out, "");
for (const t of todo) {
  if (spent >= STOP_USD) { console.log(`stopped at ${spent.toFixed(3)} USD`); break; }
  const db = fakeSupabase();
  const before = spent, t0 = Date.now();
  const row = { ...t };
  try {
    const r = await generateWordEntry({ supabaseAdmin: db, userId: null, word: t.word, nativeLanguage: "zh", pos: t.pos || null, chargeQuota: false, source: "t1 acceptance" });
    const o = db.tables.learning_objects?.find((x) => x.id === r.entryId) || db.tables.learning_objects?.[0];
    const tr = (db.tables.learning_object_translations || []).filter((x) => x.learning_object_id === o?.id);
    const meaningEn = tr.find((x) => x.native_language === "en")?.meaning || "";
    const examples = (db.tables.learning_object_examples || []).filter((x) => x.learning_object_id === o?.id).map((x) => x.example_swedish);
    const colls = (db.tables.learning_object_collocations || []).filter((x) => x.learning_object_id === o?.id).map((x) => x.phrase_text);
    const status = (db.tables.resource_field_status || []).filter((x) => x.learning_object_id === o?.id);
    const check = status.map((x) => x.detail).find((d) => d?.check_version) || {};
    Object.assign(row, { created: r.created, swedish: o?.swedish, gotPos: o?.part_of_speech, object_type: o?.object_type, status: o?.status, verification: o?.verification_status,
      meaningEn, examples: examples.length, examplesUseWord: examples.filter((e) => exampleUsesWord(e, o?.swedish, [])).length, collocations: colls,
      verdict: check.verdict, open: (check.open_items || []).map((x) => x.kind), droppedCollocations: check.dropped_collocations || [], missingSenses: (check.missing_senses || []).length });
    if (t.set !== "C") {
      const refs = await referenceEntries(null, t.word);
      row.coverageNew = coverage(refs, t.pos, meaningEn);
      if (t.set === "A") { const old = await libraryMeaning(t.word, t.pos); row.libraryMeaning = old; if (old != null) row.coverageOld = coverage(refs, t.pos, old); }
    }
  } catch (e) { row.error = String(e.message || e).slice(0, 300); }
  row.usd = +(spent - before).toFixed(4); row.ms = Date.now() - t0;
  appendFileSync(out, JSON.stringify(row) + "\n");
  console.log(`${t.set} ${t.word}${t.pos ? "/" + t.pos : ""}: ${row.error ? "ERROR " + row.error : `${row.status} ${row.gotPos} cov ${row.coverageNew ? row.coverageNew.covered + "/" + row.coverageNew.senses : "-"}`} $${row.usd} (total ${spent.toFixed(3)})`);
}
console.log({ spent: +spent.toFixed(4), calls, written: out });
